// DeliverSink describes where command output should be routed when
// --deliver is set. Parsed from the sink specifier "scheme:target".
type DeliverSink struct {
	Scheme string
	Target string
}

// ParseDeliverSink parses a --deliver value. Supported schemes:
//
//	stdout          -> default, no redirection
//	file:<path>     -> write output atomically to <path>
//	webhook:<url>   -> POST output body to <url>
//
// Returns an error for unknown schemes with a message naming the
// supported set, so agents see a structured refusal rather than a
// silent misroute.
func ParseDeliverSink(spec string) (DeliverSink, error) {
	if spec == "" || spec == "stdout" {
		return DeliverSink{Scheme: "stdout"}, nil
	}
	idx := strings.Index(spec, ":")
	if idx == -1 {
		return DeliverSink{}, fmt.Errorf("unknown --deliver sink %q: expected scheme:target (supported: stdout, file:<path>, webhook:<url>)", spec)
	}
	scheme := spec[:idx]
	target := spec[idx+1:]
	switch scheme {
	case "file":
		if target == "" {
			return DeliverSink{}, fmt.Errorf("--deliver file:<path> requires a path")
		}
	case "webhook":
		if !strings.HasPrefix(target, "http://") && !strings.HasPrefix(target, "https://") {
			return DeliverSink{}, fmt.Errorf("--deliver webhook:<url> requires an http:// or https:// URL, got %q", target)
		}
	default:
		return DeliverSink{}, fmt.Errorf("unknown --deliver scheme %q (supported: stdout, file, webhook)", scheme)
	}
	return DeliverSink{Scheme: scheme, Target: target}, nil
}

// Deliver routes a captured output buffer to the configured sink. stdout
// is a no-op because the buffer has already been streamed to stdout via
// the MultiWriter set up in root.go. ctx carries the command/MCP-call
// cancellation so a slow webhook stops when the invocation is cancelled.
func Deliver(ctx context.Context, sink DeliverSink, body []byte, compact bool) error {
	switch sink.Scheme {
	case "", "stdout":
		return nil
	case "file":
		return deliverFile(sink.Target, body)
	case "webhook":
		return deliverWebhook(ctx, sink.Target, body, compact)
	default:
		return fmt.Errorf("unsupported deliver sink %q", sink.Scheme)
	}
}

func deliverFile(path string, body []byte) error {
	// Atomic write: tmp + rename. Protects agents from seeing a partial
	// file if the process is interrupted mid-write.
	dir := filepath.Dir(path)
	if dir != "" && dir != "." {
		if err := os.MkdirAll(dir, 0o700); err != nil {
			return fmt.Errorf("creating deliver dir: %w", err)
		}
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, body, 0o600); err != nil {
		return fmt.Errorf("writing deliver tmp: %w", err)
	}
	if err := os.Rename(tmp, path); err != nil {
		return fmt.Errorf("replacing deliver file: %w", err)
	}
	return nil
}

func deliverWebhook(ctx context.Context, url string, body []byte, compact bool) error {
	contentType := "application/json"
	if compact {
		contentType = "application/x-ndjson"
	}
	if ctx == nil {
		ctx = context.Background()
	}
	// Bind the request to the command/MCP-call context so cancelling the
	// invocation aborts a slow webhook immediately instead of blocking on
	// the client timeout.
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, url, bytes.NewReader(body))
	if err != nil {
		return fmt.Errorf("building webhook request: %w", err)
	}
	req.Header.Set("Content-Type", contentType)
	req.Header.Set("User-Agent", "motogp-pp-cli/deliver")

	resp, err := newWebhookClient().Do(req)
	if err != nil {
		return fmt.Errorf("posting to webhook: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 400 {
		return fmt.Errorf("webhook returned %s", resp.Status)
	}
	return nil
}

// newWebhookClient builds an HTTP client hardened against SSRF. Because
// --deliver webhook is mirrored into the MCP server, an agent-supplied URL
// must not be able to make this process reach loopback, private-network,
// link-local, or cloud-metadata (169.254.169.254) endpoints — directly or via
// a redirect. Enforcement is default-deny at dial time (post-DNS-resolution,
// so it also defeats DNS rebinding) and re-checked on every redirect hop.
func newWebhookClient() *http.Client {
	control := func(_ /*network*/, address string, _ syscall.RawConn) error {
		host, _, err := net.SplitHostPort(address)
		if err != nil {
			return fmt.Errorf("webhook: cannot parse dial address %q: %w", address, err)
		}
		ip := net.ParseIP(host)
		if ip == nil {
			return fmt.Errorf("webhook: unresolved dial host %q", host)
		}
		if isBlockedWebhookIP(ip) {
			return fmt.Errorf("webhook: destination %s is a loopback/private/link-local/metadata address and is blocked", ip)
		}
		return nil
	}
	transport := &http.Transport{
		// No environment proxy: with a proxy the dialer would validate the
		// proxy's IP, not the webhook destination, letting a permissive proxy
		// forward to a private/metadata address and bypass the Control check
		// below. Connecting directly ensures Control sees the real (post-DNS)
		// destination IP for the original URL and every redirect hop.
		Proxy: nil,
		DialContext: (&net.Dialer{
			Timeout: 10 * time.Second,
			Control: control,
		}).DialContext,
	}
	return &http.Client{
		Timeout:   30 * time.Second,
		Transport: transport,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 5 {
				return fmt.Errorf("webhook: stopped after %d redirects", len(via))
			}
			if req.URL.Scheme != "http" && req.URL.Scheme != "https" {
				return fmt.Errorf("webhook: redirect to non-http(s) scheme %q blocked", req.URL.Scheme)
			}
			return nil
		},
	}
}

// isBlockedWebhookIP reports whether ip is an SSRF-sensitive destination that
// webhook delivery must refuse. IsPrivate covers RFC1918 + IPv6 unique-local
// (fc00::/7); IsLinkLocalUnicast covers 169.254.0.0/16 and fe80::/10, which
// includes the cloud metadata address 169.254.169.254.
func isBlockedWebhookIP(ip net.IP) bool {
	if ip == nil {
		return true
	}
	return ip.IsLoopback() ||
		ip.IsPrivate() ||
		ip.IsUnspecified() ||
		ip.IsLinkLocalUnicast() ||
		ip.IsLinkLocalMulticast() ||
		ip.IsMulticast() ||
		ip.IsInterfaceLocalMulticast()
}
